-- | A call through a function pointer.
callPtr :: Ed -> P -> [Word64] -> IO Word64
callPtr ed' p args = (fnTable ! fnIndex p) ed' args

-- | The address of IObuff, for the host.
addr'IObuff :: Ed -> P
addr'IObuff ed' = pAdd (edSeg ed') 3616

