optvar_is_null :: Ed -> P -> IO Bool
optvar_is_null _ v = frame 32 $ \fr' -> do
  copyMem (pAdd fr' 0) v 32
  r'1 <- rdP fr' optvar_T'ov_int
  r'3 <- if (r'1 == nullPtr) then (do { r'2 <- rdP fr' optvar_T'ov_long; pure (r'2 == nullPtr) }) else pure False
  r'5 <- if r'3 then (do { r'4 <- rdP fr' optvar_T'ov_str; pure (r'4 == nullPtr) }) else pure False
